#!/usr/bin/env bash
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "$0")/../.." && pwd)"
E2E_DIR="$ROOT_DIR/.lrdata/e2e"
PYTHON_BIN="${PYTHON_BIN:-python3}"

export PYTHONPATH="$ROOT_DIR/scripts/e2e${PYTHONPATH:+:$PYTHONPATH}"

load_run_env() {
  if [[ -f "$E2E_DIR/run.env" ]]; then
    # Generated by the harness with 0600 permissions. Explicit caller env
    # (e.g. E2E_BASE_URL=https://manual-talent3... make e2e) wins over the
    # provisioned defaults.
    local _base="${E2E_BASE_URL:-}"
    local _api="${E2E_API_URL:-}"
    # shellcheck disable=SC1090
    source "$E2E_DIR/run.env"
    [[ -n "$_base" ]] && export E2E_BASE_URL="$_base"
    [[ -n "$_api" ]] && export E2E_API_URL="$_api"
  fi
  return 0
}

require_state() {
  if [[ ! -f "$E2E_DIR/state.json" ]]; then
    echo "No E2E run state. Start with: make dev-up NICEURL=niceurl3 (or make e2e-up)" >&2
    exit 2
  fi
}
